//! The wallpaper gallery: everything that can be decided without Windows.
//!
//! The eight wallpapers are generated by `assets/wallpapers/generate.py`. The repository keeps the
//! script, the small previews and `manifest.json`; the full-size images (about 5 MB together) are
//! attached to the release and downloaded one at a time when the user asks, checked against the
//! SHA-256 in the manifest that ships inside this exe, so the check does not depend on the server.
//!
//! Applying a wallpaper goes through the Windows desktop wallpaper service, never the registry,
//! and what was there before is remembered so it can be put back.

use serde::{Deserialize, Serialize};

pub const MANIFEST_JSON: &str = include_str!("../assets/wallpapers/manifest.json");
pub const MAX_IMAGE_BYTES: u64 = 24 * 1024 * 1024;
const MIN_IMAGE_BYTES: u64 = 10 * 1024;
const MAX_ENTRIES: usize = 16;
const MAX_PREVIOUS: usize = 8;

/// How the picture sits on a display. Windows keeps one value for all displays (see `Fit::label`
/// users), so this is remembered per wallpaper and applied together with it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Fit {
    /// Cover the display; edges are cropped when the shapes differ.
    Fill,
    /// Show the whole picture; black bars when the shapes differ (invisible on a black picture).
    Fit,
    /// Natural size in the middle.
    Center,
}

impl Fit {
    pub fn label(self) -> &'static str {
        match self {
            Fit::Fill => "Fill (crop to cover)",
            Fit::Fit => "Fit (show everything)",
            Fit::Center => "Center (actual size)",
        }
    }

    pub fn next(self) -> Fit {
        match self {
            Fit::Fill => Fit::Fit,
            Fit::Fit => Fit::Center,
            Fit::Center => Fit::Fill,
        }
    }

    /// `DESKTOP_WALLPAPER_POSITION` from `shobjidl_core.idl`.
    pub fn position(self) -> u32 {
        match self {
            Fit::Center => 0,
            Fit::Fit => 3,
            Fit::Fill => 4,
        }
    }

    pub fn from_position(position: u32) -> Option<Fit> {
        match position {
            0 => Some(Fit::Center),
            3 => Some(Fit::Fit),
            4 => Some(Fit::Fill),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Entry {
    pub id: String,
    pub name: String,
    /// Also the picture's text description for people who cannot see it.
    pub description: String,
    pub file: String,
    pub width: u32,
    pub height: u32,
    pub bytes: u64,
    pub sha256: String,
    pub fit: Fit,
}

#[derive(Deserialize)]
struct Manifest {
    schema: u32,
    wallpapers: Vec<Entry>,
}

fn valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 32
        && id
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

fn check(entry: &Entry) -> Result<(), String> {
    if !valid_id(&entry.id) {
        return Err(format!("bad id {:?}", entry.id));
    }
    if entry.name.trim().is_empty() || entry.name.chars().count() > 40 {
        return Err(format!("{}: bad name", entry.id));
    }
    if entry.description.trim().is_empty() || entry.description.chars().count() > 240 {
        return Err(format!("{}: bad description", entry.id));
    }
    let expected = format!(
        "allblack11-wallpaper-{}-{}x{}.png",
        entry.id, entry.width, entry.height
    );
    if entry.file != expected {
        return Err(format!("{}: file must be {expected}", entry.id));
    }
    if !(640..=16_384).contains(&entry.width) || !(360..=16_384).contains(&entry.height) {
        return Err(format!("{}: bad size", entry.id));
    }
    if !(MIN_IMAGE_BYTES..=MAX_IMAGE_BYTES).contains(&entry.bytes) {
        return Err(format!("{}: bad byte size", entry.id));
    }
    if !crate::sha256::is_hex_digest(&entry.sha256) {
        return Err(format!("{}: bad sha256", entry.id));
    }
    Ok(())
}

pub fn parse_manifest(text: &str) -> Result<Vec<Entry>, String> {
    let manifest: Manifest = serde_json::from_str(text).map_err(|e| e.to_string())?;
    if manifest.schema != 1 {
        return Err(format!("unknown manifest schema {}", manifest.schema));
    }
    if manifest.wallpapers.is_empty() || manifest.wallpapers.len() > MAX_ENTRIES {
        return Err("the manifest lists no wallpapers or too many".into());
    }
    let mut seen: Vec<&str> = Vec::new();
    for entry in &manifest.wallpapers {
        check(entry)?;
        if seen.contains(&entry.id.as_str()) {
            return Err(format!("{} is listed twice", entry.id));
        }
        seen.push(&entry.id);
    }
    Ok(manifest.wallpapers)
}

/// The wallpapers this build knows. An entry that fails validation is left out, never half-used.
pub fn catalog() -> Vec<Entry> {
    match parse_manifest(MANIFEST_JSON) {
        Ok(list) => list,
        Err(_) => Vec::new(),
    }
}

/// The small preview, a JPEG that ships inside the exe.
pub fn thumb_bytes(id: &str) -> Option<&'static [u8]> {
    Some(match id {
        "moonrise" => include_bytes!("../assets/wallpapers/thumbs/moonrise.jpg"),
        "eclipse" => include_bytes!("../assets/wallpapers/thumbs/eclipse.jpg"),
        "window-light" => include_bytes!("../assets/wallpapers/thumbs/window-light.jpg"),
        "horizon" => include_bytes!("../assets/wallpapers/thumbs/horizon.jpg"),
        "contour" => include_bytes!("../assets/wallpapers/thumbs/contour.jpg"),
        "orbit" => include_bytes!("../assets/wallpapers/thumbs/orbit.jpg"),
        "dot-matrix" => include_bytes!("../assets/wallpapers/thumbs/dot-matrix.jpg"),
        "ridges" => include_bytes!("../assets/wallpapers/thumbs/ridges.jpg"),
        _ => return None,
    })
}

/// The release the full-size images are attached to: the one for this version of the app.
pub fn release_tag() -> String {
    format!("v{}", env!("CARGO_PKG_VERSION"))
}

/// Where the full image is downloaded from. Only this repository's release assets, only the
/// file names the manifest lists.
pub fn asset_url(tag: &str, entry: &Entry) -> Option<String> {
    if tag.is_empty()
        || !tag
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
    {
        return None;
    }
    let url = format!(
        "https://github.com/{}/{}/releases/download/{tag}/{}",
        crate::update::REPO_OWNER,
        crate::update::REPO_NAME,
        entry.file
    );
    crate::update::is_release_asset_url(&url, tag).then_some(url)
}

/// "5.4 MB" or "630 KB", for the button that starts a download.
pub fn size_text(bytes: u64) -> String {
    crate::update::format_bytes(bytes)
}

// ---------------------------------------------------------------------------------------------
// What is remembered
// ---------------------------------------------------------------------------------------------

/// What a display showed before AllBlack11 changed it.
#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize, Serialize)]
pub struct Previous {
    /// The display's identifier from Windows; empty for "all displays".
    pub monitor: String,
    /// The picture path, empty when it was a solid color or a slideshow (those cannot be put back).
    pub path: String,
    pub position: u32,
}

#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize, Serialize)]
pub struct Applied {
    pub id: String,
    /// The display it went to; empty for all displays.
    pub monitor: String,
    pub fit: Option<Fit>,
}

#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize, Serialize)]
#[serde(default)]
pub struct State {
    pub applied: Option<Applied>,
    /// Fit chosen per wallpaper: (id, fit).
    pub fits: Vec<(String, Fit)>,
    /// How to go back, from the last apply only.
    pub previous: Vec<Previous>,
    /// The desktop background color before the last apply changed it (letterbox bars), if it did.
    pub previous_background: Option<u32>,
}

impl State {
    /// A damaged or unknown file is "nothing remembered", never an error.
    pub fn parse(text: &str) -> State {
        let mut state: State = serde_json::from_str(text).unwrap_or_default();
        state.previous.truncate(MAX_PREVIOUS);
        state.fits.truncate(MAX_ENTRIES);
        state
    }

    pub fn to_json(&self) -> String {
        serde_json::to_string_pretty(self).unwrap_or_else(|_| "{}".to_string()) + "\n"
    }

    pub fn fit_for(&self, entry: &Entry) -> Fit {
        self.fits
            .iter()
            .find(|(id, _)| *id == entry.id)
            .map(|(_, fit)| *fit)
            .unwrap_or(entry.fit)
    }

    pub fn set_fit(&mut self, id: &str, fit: Fit) {
        match self.fits.iter_mut().find(|(known, _)| known == id) {
            Some(slot) => slot.1 = fit,
            None => self.fits.push((id.to_string(), fit)),
        }
        self.fits.truncate(MAX_ENTRIES);
    }

    pub fn remember_apply(
        &mut self,
        applied: Applied,
        previous: Vec<Previous>,
        previous_background: Option<u32>,
    ) {
        self.applied = Some(applied);
        self.previous = previous;
        self.previous.truncate(MAX_PREVIOUS);
        self.previous_background = previous_background;
    }

    pub fn can_put_back(&self) -> bool {
        self.previous.iter().any(|p| !p.path.is_empty())
    }
}

/// The line under a wallpaper in the grid.
pub fn status_text(entry: &Entry, downloaded: bool, state: &State) -> String {
    let applied = state
        .applied
        .as_ref()
        .is_some_and(|applied| applied.id == entry.id);
    match (applied, downloaded) {
        (true, _) => "In use".to_string(),
        (false, true) => "On this PC".to_string(),
        (false, false) => format!("Download {}", size_text(entry.bytes)),
    }
}

/// How the picture is placed inside a display of `monitor` pixels, as the destination rectangle
/// (left, top, width, height) relative to the display and the part of the picture shown
/// (left, top, width, height). Used by the full-screen preview, so it shows what Windows will do.
pub fn placement(
    fit: Fit,
    image: (u32, u32),
    monitor: (u32, u32),
) -> ((i32, i32, i32, i32), (i32, i32, i32, i32)) {
    let (iw, ih) = (image.0.max(1) as i64, image.1.max(1) as i64);
    let (mw, mh) = (monitor.0.max(1) as i64, monitor.1.max(1) as i64);
    let whole = (0, 0, iw as i32, ih as i32);
    match fit {
        Fit::Center => {
            // Actual size: crop what does not fit, center what does.
            let show_w = iw.min(mw);
            let show_h = ih.min(mh);
            (
                (
                    ((mw - show_w) / 2) as i32,
                    ((mh - show_h) / 2) as i32,
                    show_w as i32,
                    show_h as i32,
                ),
                (
                    ((iw - show_w) / 2) as i32,
                    ((ih - show_h) / 2) as i32,
                    show_w as i32,
                    show_h as i32,
                ),
            )
        }
        Fit::Fit => {
            // Scale so the whole picture shows.
            let (w, h) = if iw * mh > ih * mw {
                (mw, (ih * mw / iw).max(1))
            } else {
                ((iw * mh / ih).max(1), mh)
            };
            (
                (
                    ((mw - w) / 2) as i32,
                    ((mh - h) / 2) as i32,
                    w as i32,
                    h as i32,
                ),
                whole,
            )
        }
        Fit::Fill => {
            // Scale so the display is covered: show the middle part of the picture.
            let (sw, sh) = if iw * mh > ih * mw {
                ((ih * mw / mh).max(1), ih)
            } else {
                (iw, (iw * mh / mw).max(1))
            };
            (
                (0, 0, mw as i32, mh as i32),
                (
                    ((iw - sw) / 2) as i32,
                    ((ih - sh) / 2) as i32,
                    sw as i32,
                    sh as i32,
                ),
            )
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_shipped_manifest_is_valid_and_matches_the_design_rules() {
        let list = parse_manifest(MANIFEST_JSON).expect("the shipped manifest must validate");
        assert_eq!(list.len(), 8);
        assert_eq!(catalog().len(), 8);
        for entry in &list {
            assert_eq!((entry.width, entry.height), (3840, 2160), "{}", entry.id);
            assert!(
                entry.bytes < 3 * 1024 * 1024,
                "{} is {} bytes",
                entry.id,
                entry.bytes
            );
            assert!(entry.file.ends_with("-3840x2160.png"));
            let thumb =
                thumb_bytes(&entry.id).unwrap_or_else(|| panic!("no preview for {}", entry.id));
            assert!(
                thumb.starts_with(&[0xFF, 0xD8, 0xFF]),
                "{} preview is not a JPEG",
                entry.id
            );
            assert!(
                thumb.len() < 40 * 1024,
                "{} preview is {} bytes",
                entry.id,
                thumb.len()
            );
            assert!(asset_url("v3.8.0-preview.1", entry).is_some());
        }
        let total: u64 = list.iter().map(|e| e.bytes).sum();
        assert!(
            total < 8 * 1024 * 1024,
            "all wallpapers together are {total} bytes"
        );
    }

    #[test]
    fn the_manifest_records_that_every_image_obeys_the_oled_rules() {
        #[derive(Deserialize)]
        struct Raw {
            wallpapers: Vec<Oled>,
        }
        #[derive(Deserialize)]
        struct Oled {
            id: String,
            oled: Stats,
        }
        #[derive(Deserialize)]
        struct Stats {
            mean_luma: f64,
            black_share: f64,
            bright_share: f64,
        }
        let raw: Raw = serde_json::from_str(MANIFEST_JSON).unwrap();
        for item in raw.wallpapers {
            assert!(item.oled.black_share >= 0.70, "{}", item.id);
            assert!(item.oled.mean_luma <= 6.0, "{}", item.id);
            assert!(item.oled.bright_share <= 0.006, "{}", item.id);
        }
    }

    #[test]
    fn a_bad_manifest_is_refused_whole() {
        let good = parse_manifest(MANIFEST_JSON).unwrap();
        let mut json: serde_json::Value = serde_json::from_str(MANIFEST_JSON).unwrap();
        let tweak = |json: &serde_json::Value, key: &str, value: serde_json::Value| {
            let mut copy = json.clone();
            copy["wallpapers"][0][key] = value;
            serde_json::to_string(&copy).unwrap()
        };
        assert!(parse_manifest(&tweak(&json, "id", "Bad Id".into())).is_err());
        assert!(parse_manifest(&tweak(&json, "file", "../x.png".into())).is_err());
        assert!(parse_manifest(&tweak(&json, "sha256", "abc".into())).is_err());
        assert!(parse_manifest(&tweak(&json, "bytes", 5.into())).is_err());
        assert!(parse_manifest(&tweak(&json, "bytes", (MAX_IMAGE_BYTES + 1).into())).is_err());
        assert!(parse_manifest(&tweak(&json, "description", "".into())).is_err());
        assert!(parse_manifest("{}").is_err() && parse_manifest("nope").is_err());
        json["schema"] = 2.into();
        assert!(parse_manifest(&serde_json::to_string(&json).unwrap()).is_err());
        let mut twice = serde_json::from_str::<serde_json::Value>(MANIFEST_JSON).unwrap();
        let first = twice["wallpapers"][0].clone();
        twice["wallpapers"].as_array_mut().unwrap().push(first);
        assert!(parse_manifest(&serde_json::to_string(&twice).unwrap())
            .unwrap_err()
            .contains("twice"));
        assert_eq!(good.len(), 8);
    }

    #[test]
    fn downloads_come_only_from_this_repositorys_release_for_this_version() {
        let entry = &catalog()[0];
        let url = asset_url("v3.8.0-preview.1", entry).unwrap();
        assert!(url.starts_with(
            "https://github.com/TH0MSX/AllBlack11/releases/download/v3.8.0-preview.1/"
        ));
        assert!(url.ends_with(&entry.file));
        assert!(asset_url("v1/../../x", entry).is_none());
        let mut evil = entry.clone();
        evil.file = "a/b.png".into();
        assert!(asset_url("v3.8.0-preview.1", &evil).is_none());
        assert_eq!(release_tag(), format!("v{}", env!("CARGO_PKG_VERSION")));
    }

    #[test]
    fn fit_modes_map_to_windows_positions_and_back() {
        for fit in [Fit::Fill, Fit::Fit, Fit::Center] {
            assert_eq!(Fit::from_position(fit.position()), Some(fit));
            assert_ne!(fit.next(), fit);
        }
        assert_eq!(
            (
                Fit::Center.position(),
                Fit::Fit.position(),
                Fit::Fill.position()
            ),
            (0, 3, 4)
        );
        assert_eq!(Fit::from_position(2), None, "stretch is not offered");
        assert_eq!(Fit::Fill.next().next().next(), Fit::Fill);
    }

    #[test]
    fn state_round_trips_and_a_damaged_file_means_nothing_is_remembered() {
        let entry = catalog()[1].clone();
        let mut state = State::default();
        assert_eq!(
            state.fit_for(&entry),
            entry.fit,
            "the wallpaper's own default"
        );
        state.set_fit(&entry.id, Fit::Center);
        state.set_fit(&entry.id, Fit::Fit);
        assert_eq!(state.fits.len(), 1);
        state.remember_apply(
            Applied {
                id: entry.id.clone(),
                monitor: String::new(),
                fit: Some(Fit::Fit),
            },
            vec![Previous {
                monitor: "\\\\?\\DISPLAY#X".into(),
                path: "C:\\w.jpg".into(),
                position: 4,
            }],
            Some(0x0020_2020),
        );
        assert!(state.can_put_back());
        assert_eq!(
            State::parse(&state.to_json()).previous_background,
            Some(0x0020_2020)
        );
        let again = State::parse(&state.to_json());
        assert_eq!(again, state);
        assert_eq!(State::parse("{ not json"), State::default());
        assert_eq!(State::parse("{\"surprise\":1}"), State::default());
        let solid = State {
            previous: vec![Previous {
                monitor: String::new(),
                path: String::new(),
                position: 0,
            }],
            ..State::default()
        };
        assert!(
            !solid.can_put_back(),
            "a solid color or slideshow cannot be restored"
        );
        let many = State {
            previous: vec![Previous::default(); 50],
            ..State::default()
        };
        assert_eq!(State::parse(&many.to_json()).previous.len(), MAX_PREVIOUS);
    }

    #[test]
    fn the_line_under_a_wallpaper_says_what_a_click_will_cost() {
        let entry = catalog()[0].clone();
        let mut state = State::default();
        assert!(status_text(&entry, false, &state).starts_with("Download "));
        assert!(
            status_text(&entry, false, &state).contains("KB")
                || status_text(&entry, false, &state).contains("MB")
        );
        assert_eq!(status_text(&entry, true, &state), "On this PC");
        state.remember_apply(
            Applied {
                id: entry.id.clone(),
                monitor: String::new(),
                fit: None,
            },
            vec![],
            None,
        );
        assert_eq!(status_text(&entry, true, &state), "In use");
    }

    #[test]
    fn placement_shows_what_windows_will_do_on_each_display_shape() {
        let image = (3840, 2160);
        // Same shape: every mode fills the display.
        for fit in [Fit::Fill, Fit::Fit] {
            let (dest, src) = placement(fit, image, (1920, 1080));
            assert_eq!(dest, (0, 0, 1920, 1080));
            assert_eq!(src, (0, 0, 3840, 2160));
        }
        // Ultrawide 3440x1440: Fill crops top and bottom, Fit leaves bars at the sides.
        let (dest, src) = placement(Fit::Fill, image, (3440, 1440));
        assert_eq!(dest, (0, 0, 3440, 1440));
        assert_eq!(src.0, 0);
        assert!(src.1 > 0 && src.3 < 2160, "{src:?}");
        let (dest, src) = placement(Fit::Fit, image, (3440, 1440));
        assert_eq!(src, (0, 0, 3840, 2160));
        assert!(dest.0 > 0 && dest.1 == 0 && dest.3 == 1440, "{dest:?}");
        // Portrait display: Fit leaves bars above and below.
        let (dest, _) = placement(Fit::Fit, image, (1080, 1920));
        assert!(dest.0 == 0 && dest.1 > 0 && dest.2 == 1080, "{dest:?}");
        // Center at actual size on a larger display shows the whole picture in the middle.
        let (dest, src) = placement(Fit::Center, (1000, 500), (1920, 1080));
        assert_eq!((dest.2, dest.3, src.2, src.3), (1000, 500, 1000, 500));
        assert!(dest.0 > 0 && dest.1 > 0);
        // Nothing divides by zero.
        let _ = placement(Fit::Fill, (0, 0), (0, 0));
    }
}
